async function newPage(initScript) {
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 })
  if (initScript) await context.addInitScript(initScript)
  const page = await context.newPage()
  page.setDefaultTimeout(5000)
  await page.goto(baseUrl, { waitUntil: 'networkidle', timeout: 25000 })
  await page.getByRole('heading', { name: /Tu portafolio, en equilibrio/i }).waitFor({ state: 'visible', timeout: 8000 })
  return { context, page }
}

async function saveShot(page, name) {
  if (!page || page.isClosed()) return null
  const filename = `${name}.png`
  await page.screenshot({ path: `${evidenceDir}/${filename}`, fullPage: true, timeout: 10000 }).catch(() => {})
  return filename
}

async function addCase(name, expected, actual, passed, page, evidenceName) {
  const evidence = await saveShot(page, evidenceName || name.replace(/[^a-z0-9]+/gi, '-').toLowerCase())
  results.metadata.cases.push({ name, status: passed ? 'PASS' : 'ISSUE', expected, actual, evidence })
}

async function runCase(name, fn) {
  let page = null
  try {
    const outcome = await fn((p) => { page = p })
    await addCase(name, outcome.expected, outcome.actual, outcome.passed, page, outcome.evidence)
  } catch (error) {
    await addCase(name, 'El caso debe ejecutarse y dejar un resultado verificable.', `Excepción en el caso: ${error?.stack || error}`, false, page)
  }
}

