// Casos 2 a 5: Storage con fallos o JSON inválido.
async function storageInit(kind) {
  return async ({ kind: initKind }) => {
    const key = 'balance.portfolio.v1'
    const proto = Storage.prototype
    const native = { getItem: proto.getItem, setItem: proto.setItem, removeItem: proto.removeItem }
    Object.defineProperty(window, '__qaNativeStorage', { value: native, configurable: false })
    if (initKind === 'corrupt') {
      native.setItem.call(window.localStorage, key, '{json-corrupto')
    } else {
      proto[initKind] = function () { throw new DOMException('Blocked by QA', 'SecurityError') }
    }
  }
}

