  await context.close()
  return { expected: 'El segundo intento debe generar una nueva solicitud y terminar con precios actualizados.', actual: `Intentos=${attempts}; habilitado tras fallo=${afterFailureEnabled}; error=${errorMessage}; éxito=${successMessage}`, passed: false, evidence: '09-refresh-retry-success' }
